    for packet in packets:
        # Extract data as string from each packet
        payload = bytes(packet).decode('latin1', errors='ignore')

        # Search for the flag pattern
        if "FLAG{" in payload:
            start = payload.find("FLAG{")
            end = payload.find("}", start)
            if end != -1:
